import re
files=["corpus/knowledge/gates-survey-kumitate.md","corpus/knowledge/gates-survey-kagi.md","corpus/knowledge/verification-patterns-fleet.md","corpus/knowledge/mutation-case-kimi-census.md","corpus/knowledge/mutation-case-kagi-census.md","plans/round-3.plan.md"]
pats={"O:":r"\bO:","I:":r"\bI:","(I)":r"\(I\)","(O)/(U)":r"\((O|U)\)","U<n>":r"\bU[0-9]+\b","[OBS]":r"\[OBS\]","[INF]":r"\[INF\]","[UNK]":r"\[UNK\]","OBSERVATION":r"OBSERVATION","INFERENCE":r"INFERENCE"}
for f in files:
    L=open(f,encoding="utf-8").read().split("\n")
    c={k:sum(1 for l in L if re.search(p,l)) for k,p in pats.items()}
    print(f, " ".join("%s=%d"%(k,v) for k,v in c.items()))
